candidates.raw:
    adcs_vec3_t u, v;
    double c, s;
    adcs_vec3_t cr;
    adcs_status_t st;

    if ((primary == NULL) || (secondary == NULL) || (separation_rad == NULL) ||
        (cross_sine == NULL) || (condition_proxy == NULL))
        return ADCS_E_NULL;

    st = adcs_vec3_normalize(primary, ADCS_EPS_NORM, &u);
    if (st != ADCS_OK) {
        *separation_rad = 0.0;
        *cross_sine = 0.0;
        *condition_proxy = INFINITY;
        return ADCS_E_DEGENERATE;
    }
    st = adcs_vec3_normalize(secondary, ADCS_EPS_NORM, &v);
    if (st != ADCS_OK) {
        *separation_rad = 0.0;
        *cross_sine = 0.0;
        *condition_proxy = INFINITY;
        return ADCS_E_DEGENERATE;
    }

    c = ADCS_CLAMP(adcs_vec3_dot(&u, &v), -1.0, 1.0);
    cr = adcs_vec3_cross(&u, &v);
    s = adcs_vec3_norm(&cr);

    if (s <= ADCS_EPS_COLLINEAR) {
        *separation_rad = 0.0;
        *cross_sine = 0.0;
        *condition_proxy = INFINITY;
        return ADCS_E_DEGENERATE;
    }

    *separation_rad = atan2(s, c);
    *cross_sine = s;
    *condition_proxy = 1.0 / s;
    return ADCS_OK;
}

